update public.spell_catalog set name_ru='Оживление мертвецов', casting_time='Действие', spell_range='10 футов', area='1 куча костей или труп Среднего или Маленького гуманоида', duration='Мгновенно; контроль 24 часа', components=array['В','С','М'], material='капля крови, кусочек плоти и щепотка костяной пыли', check_type='', damage='', effect_summary='Превращаешь кости в Скелета или труп в Зомби. Созданная нежить подчиняется 24 часа. Бонусным действием можно отдавать приказ любой созданной этим заклинанием нежити в 60 футах; нескольким — один общий приказ. Без приказа она Уклоняется и двигается только ради самосохранения. До истечения 24 часов можно снова наложить заклинание и продлить контроль.', upcast='+2 оживлённых или повторно подчинённых существа за каждый уровень ячейки выше 3; для новых существ нужны разные трупы или кучи костей.', notes='Повторное применение для поддержания контроля может вернуть под контроль до 4 ранее созданных существ вместо создания нового.', author_description='Берёшь проблему с нехваткой персонала и решаешь её при помощи людей, которые уже точно не потребуют зарплату. Жрец назовёт это святотатством, если только сам не готовил это заклинание утром.', author_comment='Мёртвые не опаздывают, не спорят и работают сутки. К сожалению, профсоюз некромантов уже заинтересовался.' where slug='animate-dead';
update public.spell_catalog set name_ru='Маяк надежды', casting_time='Действие', spell_range='30 футов', area='Любое число выбранных существ в пределах дистанции', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='', damage='Лечение по целям всегда восстанавливает максимально возможное число HP', effect_summary='Выбранные цели получают преимущество на спасброски Мудрости и спасброски от смерти. Любое получаемое ими лечение восстанавливает максимальное возможное количество HP.', upcast='', notes='Работает только пока сохраняется концентрация.', author_description='Жрец поднимает всем мораль, укрепляет волю и заставляет лечение работать на максимум. Полезно настолько, что особенно раздражает.', author_comment='Иногда жрец действительно спасает всю группу. Главное — не дать ему потом неделю об этом рассказывать.' where slug='beacon-of-hope';
update public.spell_catalog set name_ru='Наложение проклятия', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости', damage='Один из вариантов: +1к8 некротического урона, когда ты наносишь цели урон атакой или заклинанием', effect_summary='При провале выбираешь одно проклятие: помеха на проверки и спасброски одной характеристики; помеха на атаки против тебя; в начале каждого хода спасбросок Мудрости, при провале цель обязана Уклоняться; либо твои атаки и заклинания наносят ей дополнительно 1к8 некротического урона.', upcast='4 уровень: концентрация до 10 минут. 5–6: без концентрации, 8 часов. 7–8: без концентрации, 24 часа. 9: без концентрации, до рассеивания.', notes='Выбор эффекта делается при наложении.', author_description='Четыре способа сделать чужую жизнь хуже одним касанием. Некроманты называют это универсальностью. Остальные — причиной носить перчатки.', author_comment='Если незнакомый маг тянется пожать тебе руку, этикет внезапно становится вопросом выживания.' where slug='bestow-curse';
update public.spell_catalog set name_ru='Мерцание', casting_time='Действие', spell_range='На себя', area='На себя', duration='1 минута', components=array['В','С'], material=null, check_type='В конце каждого своего хода бросок 1к6: на 4–6 переходишь на Эфирный план до начала следующего хода', damage='', effect_summary='В конце каждого своего хода бросаешь 1к6. На 4–6 исчезаешь на Эфирный план. Там видишь покинутый план в серых тонах до 60 футов и взаимодействуешь только с существами Эфирного плана. В начале следующего хода возвращаешься в свободное место в 10 футах от точки исчезновения.', upcast='', notes='Не требует концентрации. Если свободного места в 10 футах нет, возвращаешься в ближайшее. Если уже находишься на Эфирном плане при срабатывании, заклинание сразу заканчивается.', author_description='Каждые несколько секунд ты случайно перестаёшь присутствовать в реальности. Волшебники назвали это защитным заклинанием, а не тяжёлым симптомом.', author_comment='Надёжность примерно как у товарища, который говорит: «Я прикрою», а потом исчезает в другое измерение.' where slug='blink';
update public.spell_catalog set name_ru='Призыв молнии', casting_time='Действие', spell_range='120 футов', area='Грозовое облако: цилиндр радиусом 60 футов и высотой 10 футов; удар — радиус 5 футов', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='Спасбросок Ловкости', damage='3к10 электричеством; половина при успехе. При настоящей грозе: +1к10', effect_summary='Создаёшь над собой грозовое облако. При наложении и затем действием Магии каждый ход выбираешь точку под облаком; все существа в 5 футах от неё делают спасбросок. На открытом воздухе во время грозы используешь существующую бурю и наносишь на 1к10 больше.', upcast='+1к10 урона за каждый уровень ячейки выше 3.', notes='Нужна видимая точка над тобой для облака и видимая точка под облаком для каждого удара.', author_description='Друид перестаёт притворяться мирным любителем природы и начинает персонально назначать, в кого сегодня ударит молния.', author_comment='Если друид говорит, что природа никого не судит, не спорь. Облако уже выбрало присяжных.' where slug='call-lightning';
update public.spell_catalog set name_ru='Ясновидение', casting_time='Действие', spell_range='1 миля', area='1 невидимый неподвижный сенсор', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='фокус стоимостью 100+ зм: украшенный рог для слуха или стеклянный глаз для зрения', check_type='', damage='', effect_summary='Создаёшь невидимый неосязаемый неуязвимый сенсор в знакомом месте или очевидной точке вроде пространства за дверью. Выбираешь зрение или слух и воспринимаешь через сенсор словно находишься там. Бонусным действием можно переключаться между зрением и слухом.', upcast='', notes='Сенсор неподвижен. Его могут увидеть существа, способные видеть невидимое или обладающие истинным зрением.', author_description='Оставляешь магический глаз или ухо там, куда сам идти не хочешь. Очень разумно. Подозрительно разумно для заклинателя.', author_comment='Настоящее приключение начинается там, где ты сначала послал вперёд магический глаз, а он увидел причину не идти.' where slug='clairvoyance';
update public.spell_catalog set name_ru='Призыв животных', casting_time='Действие', spell_range='60 футов', area='Спектральная стая; опасная зона в 10 футах от неё', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='Спасбросок Ловкости; не чаще 1 раза за ход на существо', damage='3к10 рубящего урона при провале', effect_summary='Призываешь большую стаю неосязаемых природных духов в облике животных. Пока находишься в 5 футах от стаи, получаешь преимущество на спасброски Силы. Когда двигаешься в свой ход, можешь переместить стаю до 30 футов. Когда стая подходит в 10 футов к видимому существу, либо существо входит туда или заканчивает там ход, можно заставить его сделать спасбросок.', upcast='+1к10 урона за каждый уровень ячейки выше 3.', notes='Одно существо делает этот спасбросок не чаще одного раза за ход.', author_description='Друид вызывает целую призрачную стаю. Не потому что одного зверя было недостаточно, а потому что травматология тоже заслуживает масштабирования.', author_comment='Секунду назад ты хотел погладить волка. Теперь их двадцать, они призрачные, и твоя рука снова рассматривается отдельно от тебя.' where slug='conjure-animals';
update public.spell_catalog set name_ru='Контрзаклинание', casting_time='Реакция, когда видишь в 60 футах существо, накладывающее заклинание с В, С или М компонентом', spell_range='60 футов', area='1 видимый заклинатель', duration='Мгновенно', components=array['С'], material=null, check_type='Цель делает спасбросок Телосложения', damage='', effect_summary='Пытаешься сорвать чужое заклинание. При провале спасброска заклинание рассеивается без эффекта, а потраченные на него Действие, Бонусное действие или Реакция пропадают. Если оно использовало ячейку, сама ячейка не расходуется.', upcast='', notes='Реакцию можно использовать только если видишь процесс сотворения и у заклинания есть хотя бы один из компонентов В/С/М.', author_description='Говоришь другому магу «нет» в тот самый момент, когда он уже почти закончил. Возможно, самое честное выражение профессионального уважения между волшебниками.', author_comment='Заклинание не прошло, действие потеряно, ячейка осталась. Маг цел. Его самооценка — нет.' where slug='counterspell';
update public.spell_catalog set name_ru='Создание пищи и воды', casting_time='Действие', spell_range='30 футов', area='Свободное место или контейнеры в пределах дистанции', duration='Мгновенно; пища портится через 24 часа', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Создаёшь 45 фунтов питательной, но безвкусной еды и 30 галлонов чистой воды. Еда может выглядеть как выбранная тобой пища и портится через 24 часа.', upcast='', notes='Еда питательная, но пресная. Вода чистая.', author_description='Жрец создаёт достаточно еды и воды, чтобы группа перестала жаловаться на пайки. Теперь они смогут жаловаться на вкус.', author_comment='Сорок пять фунтов еды без вкуса. Даже магия знает, что бесплатный обед имеет цену.' where slug='create-food-and-water';
update public.spell_catalog set name_ru='Дневной свет', casting_time='Действие', spell_range='60 футов', area='Сфера радиусом 60 футов или эманация от объекта', duration='1 час', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Создаёт солнечный свет: яркий в радиусе 60 футов и тусклый ещё на 60. Можно наложить на непереносимый объект; непрозрачное покрытие блокирует свет. Перекрывающаяся магическая Тьма 3 уровня или ниже рассеивается.', upcast='', notes='Не требует концентрации. Свет считается солнечным.', author_description='Сто двадцать футов света для тех, кому обычного солнца показалось недостаточно. Вампиры оценят инициативу.', author_comment='Если после этого плут всё ещё требует идти в темноте, значит дело никогда не было в освещении.' where slug='daylight';
update public.spell_catalog set name_ru='Рассеивание магии', casting_time='Действие', spell_range='120 футов', area='1 существо, объект или магический эффект', duration='Мгновенно', components=array['В','С'], material=null, check_type='Для каждого заклинания 4+ уровня: проверка характеристики заклинаний против Сл 10 + уровень заклинания', damage='', effect_summary='Все действующие заклинания 3 уровня или ниже на выбранной цели заканчиваются. Для каждого заклинания 4 уровня или выше делаешь отдельную проверку характеристики заклинаний; при успехе оно заканчивается.', upcast='Заклинания, уровень которых не выше использованной ячейки Рассеивания магии, заканчиваются автоматически.', notes='Проверяется каждое действующее заклинание на цели отдельно.', author_description='Убирает чужую магию. Чисто, быстро и без необходимости понимать, зачем другой идиот вообще её наложил.', author_comment='Волшебник час готовил магическую защиту. Ты потратил действие. Академическая карьера в одном предложении.' where slug='dispel-magic';
update public.spell_catalog set name_ru='Страх', casting_time='Действие', spell_range='На себя', area='Конус 30 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='белое перо', check_type='Спасбросок Мудрости; повтор в конце хода только если цель не видит тебя', damage='', effect_summary='Все существа в конусе при провале бросают то, что держат, и становятся Испуганными. На каждом своём ходу испуганная цель обязана Рывком уходить от тебя по максимально безопасному пути, если ей есть куда двигаться. Если заканчивает ход вне линии видимости к тебе, повторяет спасбросок и при успехе освобождается.', upcast='', notes='Повторный спасбросок появляется только если цель закончила ход там, где не видит тебя.', author_description='Показываешь группе врагов что-то настолько неприятное, что они роняют вещи и бегут. Обычно для такого достаточно показать им счёт за воскрешение.', author_comment='Если враг убегает от тебя со всех ног, не обязательно называть это победой. Но я разрешаю.' where slug='fear';
update public.spell_catalog set name_ru='Огненный шар', casting_time='Действие', spell_range='150 футов', area='Сфера радиусом 20 футов', duration='Мгновенно', components=array['В','С','М'], material='шарик из гуано летучей мыши и серы', check_type='Спасбросок Ловкости — половина урона при успехе', damage='8к6 огнём', effect_summary='В выбранной точке происходит огненный взрыв. Все существа в сфере делают спасбросок Ловкости: при провале получают полный урон, при успехе — половину. Незакреплённые горючие предметы, которые никто не носит и не держит, загораются.', upcast='+1к6 урона за каждый уровень ячейки выше 3.', notes='Не различает врагов и союзников. Центр выбирается в пределах дистанции.', author_description='Выбираешь точку в ста пятидесяти футах и превращаешь дипломатическую ситуацию в сферу радиусом двадцать футов. Восемь к6 обычно достаточно, чтобы все участники переговоров наконец пришли к одному мнению: волшебник — идиот.', author_comment='Если волшебник говорит «не переживайте, я рассчитал область», начинай бежать до того, как он закончит фразу.' where slug='fireball';
update public.spell_catalog set name_ru='Полёт', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='перо', check_type='', damage='', effect_summary='Цель получает скорость полёта 60 футов и может зависать.', upcast='+1 цель за каждый уровень ячейки выше 3.', notes='Когда заклинание заканчивается, цель падает, если всё ещё находится в воздухе и не умеет остановить падение другим способом.', author_description='Даёшь человеку полёт на десять минут. Важно помнить, что концентрация — это также десятиминутная аренда права не познакомиться с землёй.', author_comment='Перед взлётом уточни, кто именно держит концентрацию. Лучше до того, как окажешься на высоте шестидесяти футов.' where slug='fly';
